fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    
    // Since arrays are non-empty and compatible (per problem assumption),
    // we don't need to validate compatibility
    
    let output_len = std::cmp::max(m, n);
    
    // Handle broadcasting for array a
    let a_output = if m == 1 {
        // Repeat the single element output_len times
        vec![a[0]; output_len]
    } else {
        // m == output_len (since m >= n when m > 1 and arrays are compatible)
        a
    };
    
    // Handle broadcasting for array b
    let b_output = if n == 1 {
        // Repeat the single element output_len times
        vec![b[0]; output_len]
    } else {
        // n == output_len (since n >= m when n > 1 and arrays are compatible)
        b
    };
    
    (a_output, b_output)
}